  // Подреден списък {t, c} за повод (по избор – една категория); при лимит се взема по малко от всяка категория
  function wishList(occ, cat, limit) {
    const o = WISHES[occ] || WISHES.nacionalen;
    const keys = Object.keys(CATS).filter((k) => o[k] && (!cat || cat === 'all' || k === cat));
    const out = [];
    for (let i = 0; out.length < 999; i++) {
      let any = false;
      keys.forEach((k) => { if (o[k][i]) { out.push({ t: o[k][i], c: k }); any = true; } });
      if (!any) break;
    }
    return limit ? out.slice(0, limit) : out;
  }

